CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles (id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('guest','account')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, profile_id uuid NOT NULL UNIQUE REFERENCES profiles(id), username text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'player' CHECK(role IN ('player','editor','admin')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE categories (id text PRIMARY KEY, parent_id text REFERENCES categories(id), name text NOT NULL, description text NOT NULL, icon text NOT NULL, color text NOT NULL, region text NOT NULL DEFAULT 'all', tags text[] NOT NULL DEFAULT '{}');
CREATE TABLE questions (id uuid PRIMARY KEY, fact_key text NOT NULL UNIQUE, subject text NOT NULL, predicate text NOT NULL, fact text NOT NULL, intent text NOT NULL DEFAULT 'identify', text text NOT NULL, normalized_hash text NOT NULL UNIQUE, answer text NOT NULL, explanation text NOT NULL, hint text NOT NULL, difficulty text NOT NULL CHECK(difficulty IN ('easy','medium','hard','expert')), format text NOT NULL CHECK(format IN ('text','choice','ordering','word')), options jsonb, region text NOT NULL DEFAULT 'all', tags text[] NOT NULL DEFAULT '{}', status text NOT NULL CHECK(status IN ('pending','approved','archived','retired')), provenance text NOT NULL, verified_at timestamptz, expires_at timestamptz, reviewed_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX questions_pool ON questions(status,difficulty,region);
CREATE TABLE question_categories (question_id uuid NOT NULL REFERENCES questions(id), category_id text NOT NULL REFERENCES categories(id), PRIMARY KEY(question_id,category_id));
CREATE INDEX category_questions ON question_categories(category_id,question_id);
CREATE TABLE question_variants (id uuid PRIMARY KEY, question_id uuid NOT NULL REFERENCES questions(id), locale text NOT NULL DEFAULT 'ar', text text NOT NULL, normalized_hash text NOT NULL UNIQUE);
CREATE TABLE accepted_answers (question_id uuid NOT NULL REFERENCES questions(id), normalized_answer text NOT NULL, display_answer text NOT NULL, PRIMARY KEY(question_id,normalized_answer));
CREATE TABLE evidence (id uuid PRIMARY KEY, question_id uuid NOT NULL REFERENCES questions(id), url text, citation text NOT NULL, verified_at timestamptz, verification_method text NOT NULL, CHECK(url IS NOT NULL OR verification_method='deterministic'));
CREATE TABLE games (id uuid PRIMARY KEY, host_id uuid NOT NULL REFERENCES profiles(id), mode text NOT NULL CHECK(mode IN ('classic','rapid')), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','finished','abandoned')), active_team integer NOT NULL DEFAULT 0 CHECK(active_team IN(0,1)), timer integer NOT NULL CHECK(timer BETWEEN 15 AND 180), negative_scores boolean NOT NULL DEFAULT false, stealing boolean NOT NULL DEFAULT true, lifelines text[] NOT NULL, current_instance uuid, turn_team integer NOT NULL DEFAULT 0 CHECK(turn_team IN(0,1)), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX games_host ON games(host_id,created_at DESC);
CREATE TABLE teams (game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, team_index integer NOT NULL CHECK(team_index IN(0,1)), name text NOT NULL, score integer NOT NULL DEFAULT 0, PRIMARY KEY(game_id,team_index));
CREATE TABLE players (id uuid PRIMARY KEY, game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, team_index integer NOT NULL, name text NOT NULL, profile_id uuid REFERENCES profiles(id), FOREIGN KEY(game_id,team_index) REFERENCES teams(game_id,team_index));
CREATE TABLE game_participants (game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, profile_id uuid NOT NULL REFERENCES profiles(id), PRIMARY KEY(game_id,profile_id));
CREATE TABLE participant_tokens (token_hash text PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE game_categories (game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, category_id text NOT NULL REFERENCES categories(id), position integer NOT NULL, PRIMARY KEY(game_id,category_id));
CREATE TABLE game_questions (id uuid PRIMARY KEY, game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES questions(id), category_id text NOT NULL REFERENCES categories(id), value integer NOT NULL CHECK(value IN(200,400,600,800)), position integer NOT NULL, status text NOT NULL DEFAULT 'available' CHECK(status IN('available','open','revealed','completed')), opened_at timestamptz, deadline timestamptz, revealed_at timestamptz, outcome text CHECK(outcome IN('correct','incorrect','skipped')), awarded_team integer, multiplier integer NOT NULL DEFAULT 1 CHECK(multiplier IN(1,2)), hint_used boolean NOT NULL DEFAULT false, UNIQUE(game_id,question_id));
ALTER TABLE games ADD CONSTRAINT game_current_fk FOREIGN KEY(current_instance) REFERENCES game_questions(id) DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX game_question_board ON game_questions(game_id,position);
CREATE TABLE reservations (profile_id uuid NOT NULL REFERENCES profiles(id), question_id uuid NOT NULL REFERENCES questions(id), game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, PRIMARY KEY(profile_id,question_id));
CREATE TABLE exposures (profile_id uuid NOT NULL REFERENCES profiles(id), question_id uuid NOT NULL REFERENCES questions(id), category_id text NOT NULL REFERENCES categories(id), game_id uuid NOT NULL REFERENCES games(id), instance_id uuid NOT NULL REFERENCES game_questions(id), shown_at timestamptz NOT NULL DEFAULT now(), answer_revealed boolean NOT NULL DEFAULT false, outcome text CHECK(outcome IN('correct','incorrect','skipped')), completed boolean NOT NULL DEFAULT false, PRIMARY KEY(profile_id,question_id));
CREATE INDEX exposure_game ON exposures(game_id);
CREATE TABLE score_events (id uuid PRIMARY KEY, game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, instance_id uuid NOT NULL UNIQUE REFERENCES game_questions(id), team_index integer, points integer NOT NULL, outcome text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lifeline_usage (game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, team_index integer NOT NULL, kind text NOT NULL CHECK(kind IN('hint','double','extra-time')), instance_id uuid NOT NULL REFERENCES game_questions(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(game_id,team_index,kind));
CREATE TABLE favorites (profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, category_id text NOT NULL REFERENCES categories(id), PRIMARY KEY(profile_id,category_id));
CREATE TABLE candidates (id uuid PRIMARY KEY, payload jsonb NOT NULL, normalized_hash text NOT NULL, fact_key text NOT NULL, status text NOT NULL CHECK(status IN('review','duplicate','rejected','approved')), reason text, verified boolean NOT NULL DEFAULT false, verification_note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX candidates_queue ON candidates(status,created_at);
CREATE TABLE duplicate_candidates (candidate_id uuid NOT NULL REFERENCES candidates(id), question_id uuid NOT NULL REFERENCES questions(id), score real NOT NULL, reason text NOT NULL, PRIMARY KEY(candidate_id,question_id));
CREATE TABLE review_tasks (id uuid PRIMARY KEY, candidate_id uuid NOT NULL REFERENCES candidates(id), kind text NOT NULL, status text NOT NULL DEFAULT 'open', assigned_to uuid REFERENCES users(id), resolved_at timestamptz);
CREATE TABLE generation_jobs (id uuid PRIMARY KEY, category_id text NOT NULL REFERENCES categories(id), kind text NOT NULL CHECK(kind IN('arithmetic','model')), status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','finished','failed')), attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 3, count integer NOT NULL CHECK(count BETWEEN 1 AND 20), cost_cents integer NOT NULL DEFAULT 0, error text, leased_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_pending_generation ON generation_jobs(category_id,kind) WHERE status IN('queued','running');
CREATE TABLE generation_budget (day date PRIMARY KEY, reserved_cents integer NOT NULL DEFAULT 0);
CREATE TABLE reports (id uuid PRIMARY KEY, profile_id uuid REFERENCES profiles(id) ON DELETE SET NULL, question_id uuid REFERENCES questions(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY, actor_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, target text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
